const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = 'SUBSTITUA_PELA_EVOLUTION_API_KEY';
const INSTANCE = 'principal';
const CRM = 'http://lovet-crm:3000';
const WA_TOKEN = 'SUBSTITUA_PELO_WA_API_TOKEN';
const OLLAMA = 'http://host.docker.internal:11434';
const MODEL = 'llama3.1:8b';
const H_JSON = { 'Content-Type': 'application/json' };
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);
const res = await http({ method: 'GET', url: CRM + '/api/wa/followups', headers: H_CRM });
const items = res.items || [];
const out = [];
// Mensagem, número (instância do gestor) e IA vêm do CRM — editáveis pelo gestor
// em WhatsApp → Follow-up (lib/followupConfig.ts). Aqui só se envia.
const INSTANCIA = res.instancia || INSTANCE;
const primeiroNome = (nome) => { const p = String(nome || '').trim().split(/\s+/)[0] || ''; return p ? ' ' + p.charAt(0).toUpperCase() + p.slice(1).toLowerCase() : ''; };
for (const it of items) {
  // CRM antigo (sem mensagem na resposta): texto padrão da Lovet — nunca envia vazio.
  const padrao = 'Oi' + primeiroNome(it.name) + '! Passando pra saber se ficou alguma dúvida sobre o seu pedido 😊 Posso te ajudar a finalizar?';
  let msg = it.mensagem || padrao;
  if (res.usarIa && res.instrucaoIa) {
    try {
      const ai = await http({ method: 'POST', url: OLLAMA + '/api/chat', headers: H_JSON, body: { model: MODEL, stream: false, options: { temperature: 0.6 }, messages: [{ role: 'system', content: res.instrucaoIa }, { role: 'user', content: 'Cliente: ' + it.name + '. Resumo da conversa: ' + (it.history || []).map(m => (m.direction === 'in' ? 'Cliente' : 'Lovet') + ': ' + m.body).join(' | ') }] } });
      msg = String(ai.message?.content || '').trim() || it.mensagem || padrao;
    } catch (e) {
      msg = it.mensagem || padrao;
    }
  }
  if (!msg) continue;
  const sent = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCIA, headers: H_EVO, body: { number: it.phone, text: msg } });
  await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId: it.conversationId, text: msg, providerMessageId: sent?.key?.id } });
  await http({ method: 'POST', url: CRM + '/api/wa/followup-sent', headers: H_CRM, body: { conversationId: it.conversationId } });
  out.push({ json: { phone: it.phone, msg } });
  await new Promise(r => setTimeout(r, 4000));
}
return out.length ? out : [{ json: { note: 'sem follow-ups pendentes' } }];
